def render_brush(tip,dep,lag=1.12,b=1.16,b0=.7,back=.85,flex=0,tri=True):
 base=tip[0].copy();dr=np.array([0.,1.]);verts=[];cent=[]
 im=Image.new('L',(1024,1024));draw=ImageDraw.Draw(im)
 angles=np.linspace(0,2*np.pi,24)
 for t,d in zip(tip,dep):
  L=lag*d/(S*1000)
  delta=t-base;length=np.linalg.norm(delta)
  if length>1e-6:dr=delta/length
  if length>L:base=t-dr*L
  if flex:base+=flex*(t-base)
  w=max(0,(b*d-b0)/2/(S*1000));n=np.array([-dr[1],dr[0]])
  a=base+n*w;bb=base-n*w
  if w>0:
   poly=base[None,:]+(back*L*np.cos(angles))[:,None]*dr+(w*np.sin(angles))[:,None]*n
   draw.polygon([tuple(p) for p in poly],fill=255)
   if tri:draw.polygon([tuple(t),tuple(a),tuple(bb)],fill=255)
   if verts:draw.polygon([tuple(verts[-1][0]),tuple(verts[-1][1]),tuple(bb),tuple(a)],fill=255)
  verts.append([a,bb]);cent.append(base.copy())
 return np.array(im)>0,np.array(cent)
